(5023144, 732789, 99263, '<td valign="top">This shot says it all. Affluence and high society, caviar, champagne and expensive cigars. Luxury cars and classy restaurants. The lighting, the tones, exposure and pov are superb too.</td>', 'This shot says it all. Affluence and high society, caviar, champagne and expensive cigars. Luxury cars and classy restaurants. The lighting, the tones, exposure and pov are superb too.', '2008-10-24 08:08:03.000000', NULL, 1),
(5023265, 732676, 92550, '<td valign="top">I share and understand your addiction - I enjoy the shot, only complaints are that it feels a little soft and the arm detracts from the watches, which are a great subject on their own.</td>', 'I share and understand your addiction - I enjoy the shot, only complaints are that it feels a little soft and the arm detracts from the watches, which are a great subject on their own.', '2008-10-24 11:37:07.000000', NULL, 1),
(5023272, 732664, 92550, '<td valign="top">Really like the DOF on this, would like to see some additional light to see them sparkle :)</td>', 'Really like the DOF on this, would like to see some additional light to see them sparkle :)', '2008-10-24 11:39:46.000000', NULL, 1),
(5023276, 732241, 92550, '<td valign="top">I think this is a dynamite idea, but not enough sharpness on the the phone - it just feels generally soft, whereas a piece of technology like this should be really sharp.</td>', 'I think this is a dynamite idea, but not enough sharpness on the the phone - it just feels generally soft, whereas a piece of technology like this should be really sharp.', '2008-10-24 11:42:17.000000', NULL, 1),
